%[text] # Controller and Environment - Simulation Case
mdl = "CtrlEnv_TestModel";
load_system(mdl)
CtrlEnv_TestModelSetup
CtrlEnv_setSimCase_FTP75 %[output:3c5e7aa3]
simOut = sim(mdl);
%%
simData = extractTimetable(simOut.logsout);

% Signal logging names in the Measurement subsystem.
sigNames = [
  "Motor torque command"
  "Vehicle speed reference kph"
  "Vehicle speed kph"
  "Motor speed reference"
  "Motor speed"
  ];

numSigs = numel(sigNames);
for i = 1 : numSigs %[output:group:331dd1c9]
  fig = plotSimulationResultSignal( ... %[output:18e4e013] %[output:1eab08ed] %[output:309542e7] %[output:01f70396] %[output:83969a7f]
    SimData = simData, ... %[output:18e4e013] %[output:1eab08ed] %[output:309542e7] %[output:01f70396] %[output:83969a7f]
    SignalName = sigNames(i) ); %[output:18e4e013] %[output:1eab08ed] %[output:309542e7] %[output:01f70396] %[output:83969a7f]
  fig.Position(4) = 150;  % height
end  % for %[output:group:331dd1c9]
